'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),project=path.resolve(root,'../.rural-quiz-runtime/art-refinement-review-20261022'),out=path.join(root,'qa/map-legibility-20261023');fs.mkdirSync(out,{recursive:true});
async function call(tool,args=[]){return new Promise((resolve,reject)=>{const p=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let s='';p.stdout.on('data',b=>s+=b);p.stderr.on('data',b=>s+=b);const t=setTimeout(()=>{p.kill();reject(Error(tool+' timeout'));},45000);p.on('close',code=>{clearTimeout(t);let r;try{r=JSON.parse(s.slice(s.indexOf('{'),s.lastIndexOf('}')+1));}catch{return reject(Error(s.slice(0,600)));}if(code||!r.ok||r.result?.success===false)return reject(Error(s.slice(0,600)));resolve(r.result);});});}
async function evaluate(fn){let r=await call('automation_evaluate',['--fn-source',fn]);for(let i=0;i<6&&r?.result!==undefined;i++)r=r.result;return r;}
function stage(size){
 for(const dir of ['pages/game','components/game-button','components/mascot-actor'])for(const name of fs.readdirSync(path.join(root,'miniprogram',dir)).filter(n=>n.endsWith('.wxss'))){let s=fs.readFileSync(path.join(root,'miniprogram',dir,name),'utf8');if(size){s=s.replace(/@media\s*\(max-width:(\d+)px\)/g,(_,n)=>size.w<=Number(n)?'@media(min-width:0px)':'@media(max-width:0px)').replace(/@media\s*\(min-width:(\d+)px\)/g,(_,n)=>size.w>=Number(n)?'@media(min-width:0px)':'@media(max-width:0px)');if(dir==='pages/game'&&name==='index.wxss')s+=`\n.game-device{width:${size.w}px!important;height:${size.h}px!important;max-width:none!important;margin:0!important;}\n`;}fs.writeFileSync(path.join(project,'miniprogram',dir,name),s);}
 let source=fs.readFileSync(path.join(root,'miniprogram/pages/game/index.js'),'utf8');
 if(size){const from=require('./native-metrics-source.cjs'),info={windowWidth:size.w,windowHeight:size.h,screenHeight:size.h,statusBarHeight:24,safeArea:{bottom:size.h-20}},menu={left:size.w-94,bottom:62};assert(from.test(source));source=source.replace(from,'const i='+JSON.stringify(info)+',m=homeLayout.metrics(i,'+JSON.stringify(menu)+',skin.gameId);');}
 fs.writeFileSync(path.join(project,'miniprogram/pages/game/index.js'),source);
}
async function measure(){return evaluate(`async function(){const p=getCurrentPages().slice(-1)[0];p.go('home');await new Promise(r=>setTimeout(r,200));const selectors=['.game-device','.panel-body','.route-caption','.route-base','.route-caption-label','.route-caption-name','.route-caption-state','.route-caption-reward','.chapter-mascot'],q=wx.createSelectorQuery();selectors.forEach(s=>q.selectAll(s).boundingClientRect());const a=await new Promise(r=>q.exec(r));const actors=await Promise.all(p.data.journey.nodes.filter(n=>n.showMascot).map(async n=>{const component=p.selectComponent('#map-actor-'+n.id),rig=component.data.rigs[n.pose],q=wx.createSelectorQuery().in(component);q.select('.actor-source-plane').boundingClientRect();const r=await new Promise(done=>q.exec(done));return {id:n.id,pose:n.pose,plane:r[0],foot:rig.mapFoot,source:{width:rig.width,height:rig.height}};}));return {theme:p.data.skin.gameId,route:p.data.route,guide:p.data.journey.guideId||p.data.journey.nodes.slice(-1)[0].id,nodes:p.data.journey.nodes.map(n=>({id:n.id,status:n.status,showMascot:n.showMascot})),rect:Object.fromEntries(selectors.map((s,i)=>[s,a[i]])),actors};}`);}
function validate(d){const r=d.rect,issues=[],check=(v,s)=>{if(!v)issues.push(s);};
 d.nodes.forEach((n,i)=>{const card=r['.route-caption'][i],base=r['.route-base'][i],height=n.status==='completed'?76:n.status==='locked'?64:90;check(Math.abs(card.height-height)<.5,'accepted height '+n.id);check(Math.abs(card.top+card.height/2-base.top-base.height/2)<.5,'card paired '+n.id);
  for(const [selector,line]of [['.route-caption-label',14],['.route-caption-name',['current','today-locked'].includes(n.status)?22:20],['.route-caption-state',15],['.route-caption-reward',14]]){const t=r[selector][i];if(!t.height)continue;check(t.height>=line-.5,'line box '+n.id+selector);check(t.top>=card.top+4&&t.bottom<=card.bottom-4,'text inside '+n.id+selector);}
  const actor=d.actors.find(a=>a.id===n.id);if(actor){const p=actor.plane,f=actor.foot;actor.dx=p.left+p.width*f.x/actor.source.width-(base.left+base.width/2);actor.dy=p.top+p.height*f.y/actor.source.height-(base.top+base.height*65/165);check(Math.abs(actor.dx)<.5&&Math.abs(actor.dy)<.5,'feet on center '+n.id);}
 });return issues;
}
(async()=>{const followup=process.argv.includes('--home-followup'),checks=followup?JSON.parse(fs.readFileSync(path.join(out,'native-checks.json'))).checks:[];try{
 for(const size of followup?[null]:[null,{w:320,h:568},{w:430,h:932}]){
  await call('close_project_window');stage(size);await call('open_project_window',['--window-mode','liteMode']);await call('simulator_screenshot',['--path',path.join(out,'native-ready.png'),'--optimize','false']);
  const cases=followup?[['red','home'],['culture','home'],['industry','home']]:size?[['ecology','complete']]:[['red','complete'],['culture','complete'],['industry','complete'],['ecology','complete'],['red','home'],['culture','home'],['industry','home'],['ecology','home'],['ecology','chapter-4'],['ecology','locked']];
  for(const [theme,scenario]of cases){await call('automation_navigate',['--action','reLaunch','--url',`/pages/game/index?theme=${theme}&review=1&controls=0&scenario=${scenario}`]);const d=await measure(),issues=validate(d);assert.equal(d.theme,theme);assert.equal(d.route,'home');assert.equal(issues.length,0,issues.join('; '));
   const screenshot=theme+'-'+scenario+'-'+(size?.w||'host')+'-native.png';if(!size)await call('simulator_screenshot',['--path',path.join(out,screenshot),'--optimize','false']);checks.push({...d,size,scenario,...(!size?{screenshot}:{}),passed:true});fs.writeFileSync(path.join(out,'native-checks.json'),JSON.stringify({date:new Date().toISOString(),passed:checks.length===12,scope:'Actual WeChat renderer: all four themes fully completed, ecology current/fourth/today-locked, and ecology 320/430 constrained containers. Actual line boxes and primary foot anchors. Not physical phones.',checks},null,2)+'\n');console.log('PASS '+theme+' '+scenario+' '+(size?.w||'host')+' native');
  }
 }
 }finally{if(!followup){stage(null);await call('simulator_refresh');}}
})().catch(e=>{console.error(e);process.exitCode=1;});
